SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, m.medication_complexity, t.tertile, COUNT(a.hadm_id) AS num_admissions, AVG(m.medication_complexity) AS avg_medication_complexity, MIN(m.medication_complexity) AS min_medication_complexity, MAX(m.medication_complexity) AS max_medication_complexity, AVG(a.length_of_stay) AS avg_length_of_stay, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(a.hadm_id), 0) AS mortality_rate, SUM(CASE WHEN a.hadm_id IN (SELECT hadm_id FROM admissions WHERE subject_id = a.subject_id AND (charttime - intime) <= 30) THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(a.hadm_id), 0) AS readmission_rate FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN (SELECT subject_id, hadm_id, medication_complexity FROM emar WHERE medication_complexity IS NOT NULL) m ON a.subject_id = m.subject_id AND a.hadm_id = m.hadm_id JOIN (SELECT subject_id, hadm_id, tertile FROM transfers WHERE tertile IS NOT NULL) t ON a.subject_id = t.subject_id AND a.hadm_id = t.hadm_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 45 AND 55 AND a.admission_type_id IN (SELECT admission_type_id FROM admissions WHERE subject_id = a.subject_id AND (charttime - intime) <= 7) GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, t.tertile ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, t.tertile NULLS LAST;